1	/**
2	 * Server-side SFTP proxy for the in-portal file manager.
3	 *
4	 * This is a plain (non-"use server") module so it can be imported by both the
5	 * server actions (lib/actions-files.ts) and the upload/download route handler.
6	 * It never runs in the browser — the customer's root credentials stay on the
7	 * server; the browser only ever talks to our own actions/route.
8	 *
9	 * Connection target is derived EXACTLY like the server detail page:
10	 *   - dedicated-IP servers connect to their own IP on port 22
11	 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
12	 * Username is always "root"; password is `server.rootPassword`.
13	 *
14	 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
15	 * every op is backed by a small in-memory simulated filesystem so the whole
16	 * file-manager UX works end to end without a live VM.
17	 */
18	import SftpClient from "ssh2-sftp-client";
19	import { SANDBOX } from "./sandbox";
20	import { decryptSecret } from "./crypto-box";
21	
22	/**
23	 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
24	 * value and falling back to the legacy plaintext column for rows that predate
25	 * encryption. Every READ of a root password must go through this helper so both
26	 * shapes keep working transparently.
27	 */
28	export function serverRootPassword(
29	  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
30	): string | null {
31	  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
32	}
33	
34	/** The minimal shape of a Server we need to open a connection. */
35	export type SftpServer = {
36	  id: string;
37	  rootPassword: string | null;
38	  rootPasswordEnc?: string | null;
39	  sshPort: number | null;
40	  dedicatedIp?: { address: string } | null;
41	};
42	
43	export type SftpEntry = {
44	  name: string;
45	  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
46	  type: string;
47	  isDirectory: boolean;
48	  size: number;
49	  /** Unix mtime in ms. */
50	  modifiedMs: number;
51	  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
52	  mode: number | null;
53	};
54	
55	export type SftpStat = {
56	  isDirectory: boolean;
57	  size: number;
58	  modifiedMs: number;
59	  mode: number | null;
60	};
61	
62	const CONNECT_TIMEOUT_MS = 10_000;
63	
64	/** Max length for any absolute path we accept from the client. */
65	export const MAX_PATH_LEN = 4096;
66	/** Max length for a single path segment (file/folder name). */
67	export const MAX_NAME_LEN = 255;
68	
69	/**
70	 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
71	 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
72	 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
73	 * "/". Throws on anything suspicious — callers surface the message.
74	 */
75	export function normalizePath(input: string): string {
76	  if (typeof input !== "string") throw new Error("Invalid path.");
77	  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
78	  if (input.includes("\0")) throw new Error("Invalid path.");
79	  if (!input.startsWith("/")) throw new Error("Path must be absolute.");
80	
81	  const out: string[] = [];
82	  for (const part of input.split("/")) {
83	    if (part === "" || part === ".") continue;
84	    if (part === "..") throw new Error("Path traversal is not allowed.");
85	    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
86	    out.push(part);
87	  }
88	  return "/" + out.join("/");
89	}
90	
91	/**
92	 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
93	 * not "." or "..". Returns the name unchanged if valid.
94	 */
95	export function validateName(name: string): string {
96	  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
97	  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
98	  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
99	  if (name === "." || name === "..") throw new Error("That name is not allowed.");
100	  return name;
101	}
102	
103	/** Join a validated absolute dir with a validated name, re-normalizing. */
104	export function joinPath(dir: string, name: string): string {
105	  return normalizePath(`${dir}/${name}`);
106	}
107	
108	/**
109	 * Fixed directory every browser→server upload lands in. Uploads are ALWAYS
110	 * written here under a sanitized basename — never at a client-chosen path — so
111	 * a hostile filename can only ever create a file inside this one dir. Lives in
112	 * this plain module (not the "use server" action file) so it can be imported
113	 * and unit-tested without pulling in the server-action graph.
114	 */
115	export const UPLOAD_DIR = "/root/nxeon-uploads";
116	
117	/**
118	 * Reduce an arbitrary, client-supplied filename to a SAFE basename that can only
119	 * land inside {@link UPLOAD_DIR}. Strips every directory component (POSIX `/`
120	 * and Windows `\`) so `../../etc/passwd` or `C:\evil\x` collapse to their final
121	 * segment, then runs the survivor through the same `validateName` the file
122	 * manager uses (rejects `/`, NUL, `.`, `..`, over-long names). Pure so the guard
123	 * can be unit-tested in isolation from any SFTP connection.
124	 */
125	export function sanitizeUploadName(raw: string): string {
126	  if (typeof raw !== "string") throw new Error("A name is required.");
127	  const base = raw.split(/[/\\]/).pop() ?? "";
128	  const trimmed = base.trim();
129	  if (!trimmed) throw new Error("A name is required.");
130	  return validateName(trimmed);
131	}
132	
133	/**
134	 * Resolve the {host, port} for a server, mirroring the server detail page:
135	 * dedicated IP -> :22, otherwise PUBLIC_IP:sshPort.
136	 */
137	export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
138	  const dedicated = !!server.dedicatedIp;
139	  const host = dedicated ? server.dedicatedIp!.address : process.env.PUBLIC_IP || "";
140	  const port = dedicated ? 22 : server.sshPort;
141	  if (!host || !port) return null;
142	  return { host, port };
143	}
144	
145	/**
146	 * Open an SFTP connection, run `fn(client)`, and ALWAYS close it (finally).
147	 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
148	 * the in-memory filesystem before ever reaching here.
149	 */
150	export async function withSftp<T>(
151	  server: SftpServer,
152	  fn: (client: SftpClient) => Promise<T>
153	): Promise<T> {
154	  if (SANDBOX) {
155	    throw new Error("withSftp must not be called in sandbox mode");
156	  }
157	  const target = connectionTarget(server);
158	  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
159	  const password = serverRootPassword(server);
160	  if (!password) throw new Error("Server has no root password set.");
161	
162	  const client = new SftpClient();
163	  try {
164	    await client.connect({
165	      host: target.host,
166	      port: target.port,
167	      username: "root",
168	      password,
169	      readyTimeout: CONNECT_TIMEOUT_MS,
170	    });
171	    return await fn(client);
172	  } finally {
173	    try {
174	      await client.end();
175	    } catch {
176	      /* best-effort close */
177	    }
178	  }
179	}
180	
181	// ----------------------------------------------------------------------------
182	// Sandbox in-memory filesystem
183	// ----------------------------------------------------------------------------
184	
185	type SimNode =
186	  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
187	  | { type: "file"; mtime: number; mode: number; content: string };
188	type SimDir = Extract<SimNode, { type: "dir" }>;
189	
190	/** One simulated filesystem per server id, lazily seeded. */
191	const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
192	const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
193	globalForSim.__nxeonSftpSim = simStore;
194	
195	function seedSim(): SimNode {
196	  const now = Date.now();
197	  const file = (content: string, mode = 0o644): SimNode => ({
198	    type: "file",
199	    mtime: now,
200	    mode,
201	    content,
202	  });
203	  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
204	    type: "dir",
205	    mtime: now,
206	    mode,
207	    children,
208	  });
209	  return dir({
210	    root: dir({
211	      "readme.txt": file(
212	        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
213	      ),
214	      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
215	      projects: dir({
216	        "app.js": file("console.log('hello from your server');\n"),
217	        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
218	      }),
219	    }),
220	    etc: dir({
221	      "hostname": file("nxeon-vps\n"),
222	      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
223	    }),
224	    var: dir({
225	      log: dir({
226	        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
227	      }),
228	      www: dir({
229	        html: dir({
230	          "index.html": file("<!doctype html><h1>It works</h1>\n"),
231	        }),
232	      }),
233	    }),
234	    tmp: dir({}),
235	  });
236	}
237	
238	function simRoot(serverId: string): SimNode {
239	  let node = simStore.get(serverId);
240	  if (!node) {
241	    node = seedSim();
242	    simStore.set(serverId, node);
243	  }
244	  return node;
245	}
246	
247	/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
248	function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
249	  if (!rights) return null;
250	  const bits = (s: string): number =>
251	    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
252	  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
253	}
254	
255	function splitPath(p: string): string[] {
256	  return p.split("/").filter((s) => s.length > 0);
257	}
258	
259	function simResolve(serverId: string, p: string): SimNode | null {
260	  let node = simRoot(serverId);
261	  for (const part of splitPath(p)) {
262	    if (node.type !== "dir") return null;
263	    const next = node.children[part];
264	    if (!next) return null;
265	    node = next;
266	  }
267	  return node;
268	}
269	
270	function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
271	  const parts = splitPath(p);
272	  if (parts.length === 0) return null;
273	  const name = parts[parts.length - 1];
274	  const parentPath = "/" + parts.slice(0, -1).join("/");
275	  const parent = simResolve(serverId, parentPath);
276	  if (!parent || parent.type !== "dir") return null;
277	  return { parent, name };
278	}
279	
280	// ----------------------------------------------------------------------------
281	// Typed operations (sandbox-aware)
282	// ----------------------------------------------------------------------------
283	
284	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
285	  if (SANDBOX) {
286	    const node = simResolve(server.id, path);
287	    if (!node) throw new Error("No such directory.");
288	    if (node.type !== "dir") throw new Error("Not a directory.");
289	    return Object.entries(node.children)
290	      .map(([name, child]) => ({
291	        name,
292	        type: child.type === "dir" ? "d" : "-",
293	        isDirectory: child.type === "dir",
294	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
295	        modifiedMs: child.mtime,
296	        mode: child.mode,
297	      }))
298	      .sort((a, b) =>
299	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
300	      );
301	  }
302	
303	  return withSftp(server, async (client) => {
304	    const list = await client.list(path);
305	    return list
306	      .map((e) => ({
307	        name: e.name,
308	        type: e.type,
309	        isDirectory: e.type === "d",
310	        size: e.size,
311	        modifiedMs: e.modifyTime,
312	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
313	        // mode — derive the octal permission bits from them.
314	        mode: rightsToMode(e.rights),
315	      }))
316	      .sort((a, b) =>
317	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
318	      );
319	  });
320	}
321	
322	export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
323	  if (SANDBOX) {
324	    const node = simResolve(server.id, path);
325	    if (!node) throw new Error("No such file or directory.");
326	    return {
327	      isDirectory: node.type === "dir",
328	      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
329	      modifiedMs: node.mtime,
330	      mode: node.mode,
331	    };
332	  }
333	
334	  return withSftp(server, async (client) => {
335	    const s = await client.stat(path);
336	    return {
337	      isDirectory: s.isDirectory,
338	      size: s.size,
339	      modifiedMs: s.modifyTime,
340	      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
341	    };
342	  });
343	}
344	
345	/**
346	 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
347	 * the cap so we never buffer an unbounded file into memory / the editor.
348	 */
349	export async function readFileText(
350	  server: SftpServer,
351	  path: string,
352	  maxBytes: number
353	): Promise<string> {
354	  if (SANDBOX) {
355	    const node = simResolve(server.id, path);
356	    if (!node) throw new Error("No such file.");
357	    if (node.type !== "file") throw new Error("Not a file.");
358	    if (Buffer.byteLength(node.content) > maxBytes) {
359	      throw new Error("File is too large to edit in the browser.");
360	    }
361	    return node.content;
362	  }
363	
364	  return withSftp(server, async (client) => {
365	    const s = await client.stat(path);
366	    if (s.isDirectory) throw new Error("Not a file.");
367	    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
368	    const buf = (await client.get(path)) as Buffer;
369	    return buf.toString("utf8");
370	  });
371	}
372	
373	export async function writeFileText(
374	  server: SftpServer,
375	  path: string,
376	  content: string
377	): Promise<void> {
378	  if (SANDBOX) {
379	    const loc = simParent(server.id, path);
380	    if (!loc) throw new Error("Invalid path.");
381	    const existing = loc.parent.children[loc.name];
382	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
383	    loc.parent.children[loc.name] = {
384	      type: "file",
385	      mtime: Date.now(),
386	      mode: existing?.type === "file" ? existing.mode : 0o644,
387	      content,
388	    };
389	    return;
390	  }
391	
392	  await withSftp(server, async (client) => {
393	    await client.put(Buffer.from(content, "utf8"), path);
394	  });
395	}
396	
397	export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
398	  if (SANDBOX) {
399	    const loc = simParent(server.id, path);
400	    if (!loc) throw new Error("Invalid path.");
401	    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
402	    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
403	    return;
404	  }
405	
406	  await withSftp(server, async (client) => {
407	    await client.mkdir(path, false);
408	  });
409	}
410	
411	export async function renamePath(
412	  server: SftpServer,
413	  from: string,
414	  to: string
415	): Promise<void> {
416	  if (SANDBOX) {
417	    const src = simResolve(server.id, from);
418	    if (!src) throw new Error("No such file or directory.");
419	    const dst = simParent(server.id, to);
420	    if (!dst) throw new Error("Invalid destination.");
421	    if (dst.parent.children[dst.name]) {
422	      throw new Error("A file or folder with that name already exists.");
423	    }
424	    const srcLoc = simParent(server.id, from);
425	    if (!srcLoc) throw new Error("Cannot rename the root.");
426	    delete srcLoc.parent.children[srcLoc.name];
427	    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
428	    return;
429	  }
430	
431	  await withSftp(server, async (client) => {
432	    await client.rename(from, to);
433	  });
434	}
435	
436	/** Remove a file, or recursively remove a directory. */
437	export async function removePath(server: SftpServer, path: string): Promise<void> {
438	  if (SANDBOX) {
439	    const loc = simParent(server.id, path);
440	    if (!loc) throw new Error("Cannot remove the root.");
441	    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
442	    delete loc.parent.children[loc.name];
443	    return;
444	  }
445	
446	  await withSftp(server, async (client) => {
447	    const s = await client.stat(path);
448	    if (s.isDirectory) {
449	      await client.rmdir(path, true); // recursive
450	    } else {
451	      await client.delete(path);
452	    }
453	  });
454	}
455	
456	export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
457	  if (SANDBOX) {
458	    const node = simResolve(server.id, path);
459	    if (!node) throw new Error("No such file or directory.");
460	    node.mode = mode & 0o777;
461	    return;
462	  }
463	
464	  await withSftp(server, async (client) => {
465	    await client.chmod(path, mode & 0o777);
466	  });
467	}
468	
469	// ----------------------------------------------------------------------------
470	// Streaming helpers for the upload/download route
471	// ----------------------------------------------------------------------------
472	
473	/** Read an entire file into a Buffer (used by the download endpoint). */
474	export async function readFileBuffer(server: SftpServer, path: string): Promise<Buffer> {
475	  if (SANDBOX) {
476	    const node = simResolve(server.id, path);
477	    if (!node) throw new Error("No such file.");
478	    if (node.type !== "file") throw new Error("Not a file.");
479	    return Buffer.from(node.content, "utf8");
480	  }
481	
482	  return withSftp(server, async (client) => {
483	    const s = await client.stat(path);
484	    if (s.isDirectory) throw new Error("Not a file.");
485	    return (await client.get(path)) as Buffer;
486	  });
487	}
488	
489	/** Write a Buffer to a path (used by the upload endpoint). */
490	export async function writeFileBuffer(
491	  server: SftpServer,
492	  path: string,
493	  data: Buffer
494	): Promise<void> {
495	  if (SANDBOX) {
496	    const loc = simParent(server.id, path);
497	    if (!loc) throw new Error("Invalid path.");
498	    const existing = loc.parent.children[loc.name];
499	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
500	    loc.parent.children[loc.name] = {
501	      type: "file",
502	      mtime: Date.now(),
503	      mode: existing?.type === "file" ? existing.mode : 0o644,
504	      content: data.toString("utf8"),
505	    };
506	    return;
507	  }
508	
509	  await withSftp(server, async (client) => {
510	    await client.put(data, path);
511	  });
512	}
