/**
 * Safe remote command runner for the LIVE Soul Pilates box (.200).
 * - Fetches server cmsc9l72y000ghl7iyd87u5ja from the Nxeon DB
 * - Derives host/port/password exactly like the portal (lib/sftp connectionTarget + serverRootPassword)
 * - ASSERTS `hostname -I` contains 51.79.226.200 before running the requested command
 * Usage: tsx run200.ts '<remote bash command>'
 */
import { PrismaClient } from "@prisma/client";
import { Client } from "ssh2";
import { connectionTarget, serverRootPassword } from "/opt/nxeon/lib/sftp";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const REQUIRED_IP = "51.79.226.200";

function execOnce(conn: Client, command: string, timeoutMs = 120_000): Promise<{ code: number | null; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let stdout = "", stderr = "", settled = false;
      const timer = setTimeout(() => { if (!settled) { settled = true; try { stream.close(); } catch {} reject(new Error("timeout")); } }, timeoutMs);
      stream.on("close", (code: number | null) => { if (!settled) { settled = true; clearTimeout(timer); resolve({ code, stdout, stderr }); } })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

async function main() {
  const command = process.argv[2];
  if (!command) throw new Error("no command given");
  const prisma = new PrismaClient();
  const server = await prisma.server.findUnique({ where: { id: SERVER_ID }, include: { dedicatedIp: true } });
  await prisma.$disconnect();
  if (!server) throw new Error("server not found");
  const target = connectionTarget(server as any);
  if (!target) throw new Error("no connection target");
  const password = serverRootPassword(server as any);
  if (!password) throw new Error("no password");

  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    const t = setTimeout(() => { try { conn.end(); } catch {} reject(new Error("connect timeout")); }, 15000);
    conn.on("ready", () => { clearTimeout(t); resolve(); })
      .on("error", (e) => { clearTimeout(t); reject(e); })
      .connect({ host: target.host, port: target.port, username: "root", password, readyTimeout: 15000 });
  });
  try {
    const idc = await execOnce(conn, "hostname -I");
    if (!idc.stdout.includes(REQUIRED_IP)) {
      throw new Error(`SAFETY ABORT: hostname -I did not contain ${REQUIRED_IP}. Got: ${idc.stdout.trim()}`);
    }
    const r = await execOnce(conn, command);
    process.stdout.write(r.stdout);
    if (r.stderr) process.stderr.write("\n[stderr]\n" + r.stderr);
    process.stderr.write(`\n[exit ${r.code}]\n`);
    process.exitCode = r.code === 0 ? 0 : (r.code ?? 1);
  } finally {
    try { conn.end(); } catch {}
  }
}
main().catch((e) => { console.error("ERROR:", e.message); process.exit(1); });

