// SFTP get/put for the .200 box, deriving creds like the portal.
// Usage: tsx _sftp200_tmp.ts get <remotePath> <localPath>
//        tsx _sftp200_tmp.ts put <localPath> <remotePath>
import { PrismaClient } from "@prisma/client";
import { connectionTarget, serverRootPassword } from "./lib/sftp";
import SftpClient from "ssh2-sftp-client";
import { readFileSync, writeFileSync } from "node:fs";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";

async function main() {
  const [op, a, b] = process.argv.slice(2);
  const prisma = new PrismaClient();
  const server = await prisma.server.findUnique({ where: { id: SERVER_ID }, include: { dedicatedIp: true } });
  await prisma.$disconnect();
  if (!server) throw new Error("server not found");
  const target = connectionTarget(server as any);
  const password = serverRootPassword(server as any);
  if (!target || !password) throw new Error("no target/password");
  const c = new SftpClient();
  await c.connect({ host: target.host, port: target.port, username: "root", password, readyTimeout: 15000 });
  try {
    if (op === "get") { const buf = (await c.get(a)) as Buffer; writeFileSync(b, buf); console.log("got", buf.length, "bytes"); }
    else if (op === "put") { await c.put(readFileSync(a), b); console.log("put ok"); }
    else throw new Error("op must be get|put");
  } finally { await c.end(); }
}
main().catch((e) => { console.error("ERROR:", e.message); process.exit(1); });

