/// <summary>
/// The share of a paid amount that is the online (Stripe) pass-through fee, NOT
/// studio revenue: <c>OnlineFeeAmount / TotalNet</c>, clamped to <c>[0,1]</c>.
/// This is the ONE definition of "how much of a payment is the online fee"; every
/// revenue surface multiplies a collected amount by <c>(1 - ratio)</c> so the fee
/// is excluded from revenue identically. The fee itself is still stored on and
/// printed on the invoice — only the REVENUE metric nets it out.
/// </summary>
private static decimal OnlineFeeRatio(decimal onlineFeeAmount, decimal totalNet) =>
    totalNet > 0m ? Math.Clamp(onlineFeeAmount / totalNet, 0m, 1m) : 0m;

/// <summary>
/// Map of invoice id → online-fee ratio (see <see cref="OnlineFeeRatio"/>) for the
/// given ids, excluding VOIDED invoices. Revenue surfaces that only have Payment
/// rows (no loaded invoices) use this to net the fee out of each payment, staying
/// consistent with <see cref="SumCollectedAsync"/>. An id absent from the map (a
/// voided or orphaned invoice) is left to the caller's existing inclusion rule.
/// </summary>
private async Task<Dictionary<string, decimal>> FeeRatioByInvoiceAsync(IEnumerable<string?> invoiceIds)
{
    var ids = invoiceIds
        .Where(id => !string.IsNullOrEmpty(id))
        .Select(id => id!)
        .Distinct()
        .ToList();
    if (ids.Count == 0) return new Dictionary<string, decimal>();
    return (await _invoices
            .Find(Builders<Invoice>.Filter.And(
                Builders<Invoice>.Filter.In(i => i.Id, ids),
                Builders<Invoice>.Filter.Ne(i => i.Status, "VOIDED")))
            .Project(i => new { i.Id, i.OnlineFeeAmount, i.TotalNet })
            .ToListAsync())
        .ToDictionary(i => i.Id!, i => OnlineFeeRatio(i.OnlineFeeAmount, i.TotalNet));
}

