import { PrismaClient } from "@prisma/client";
const prisma = new PrismaClient();
const BOARD = "cmsavfvil000hhla4nlpuyge6";
const COL = "cmsavfvin000khla4anofdbxt";

const body = [
  "**Claude** — Revenue now excludes the online/Stripe pass-through fee.",
  "",
  "**What changed** (`SoulPilates.Services/AnalyticsService.cs` only): every revenue surface now nets out each invoice's `OnlineFeeAmount` (the 5% Stripe/online surcharge), mirroring the existing `SumCollectedAsync` fee-ratio approach via two new shared helpers — `OnlineFeeRatio(fee, totalNet)` and `FeeRatioByInvoiceAsync(ids)`.",
  "",
  "**Revenue surfaces corrected:**",
  "- Dashboard month revenue (`GetDashboardKpisAsync`→`SumCollectedAsync`) — already correct, now the single source of the formula.",
  "- `GetMonthSummaryAsync` headline `TotalRevenueVnd` (drives today/month revenue, daily average, monthly projection).",
  "- `GetBusinessSummaryAsync` (`/api/analytics/business-summary`) revenue + profit — reuses the month summary.",
  "- `GetRevenueBreakdownAsync` total.",
  "- Top-clients revenue, customer-segmentation revenue.",
  "- Payment-method distribution revenue.",
  "- Daily time-series `revenue` and `profit` metrics.",
  "- Yearly revenue/expense.",
  "- Revenue Forecast: untouched — it's price-based on future bookings, the fee never enters it.",
  "",
  "**Invoices are unchanged** — the fee is STILL stored (`InvoiceService.cs:90` folds it into `TotalNet`) and STILL printed on receipts (`InvoiceReceiptDocument.cs` \"VAT (online only)\"). The customer paid it; only the REVENUE metric nets it out. Commission/payroll untouched.",
  "",
  "Revenue is computed live from the data, so existing payments are corrected automatically — e.g. Eva Kretsova's SP-INV-260809-0004: 2,362,500 → 2,250,000.",
  "",
  "**Builds (throwaway `--rm` containers):** `dotnet build SoulPilates.API -c Release` (dotnet/sdk:10.0) → **0 errors** (65 pre-existing warnings); `npm ci && npm run build` (node:22-alpine) → **success, 62 pages**.",
  "",
  "**Branch:** `feature/exclude-online-fee-revenue` (off deployed `origin/feature/notes-commission-override`).",
  "**Tip:** `249f39fa1915ed72b88d5eeb4b2a2be337e69287`.",
  "",
  "**Not deployed** (isolated/compile-verify only). Deploy on the LIVE box (51.79.226.200):",
  "```",
  "cd /opt/soulpilates && git fetch origin && git checkout -B main origin/feature/exclude-online-fee-revenue && scripts/deploy-prod.sh",
  "```",
].join("\n");

async function main() {
  const col = await prisma.boardColumn.findUnique({ where: { id: COL } });
  if (!col || col.boardId !== BOARD) throw new Error("column/board mismatch");
  const count = await prisma.card.count({ where: { columnId: COL, archivedAt: null } });
  const card = await prisma.card.create({
    data: {
      boardId: BOARD,
      columnId: COL,
      title: "Revenue: exclude Stripe/online fee",
      type: "FEATURE",
      assignee: "claude",
      position: count,
      description: "Revenue metrics must not count the online/Stripe pass-through fee (OnlineFeeAmount) as studio earnings. Fixed in AnalyticsService.cs; invoices still store & show the fee.",
      comments: { create: { authorName: "Claude", body } },
    },
    include: { comments: true },
  });
  console.log("card:", card.id, "| comment:", card.comments[0].id);
  await prisma.$disconnect();
}
main().catch((e) => { console.error("ERROR:", e.message); process.exit(1); });
